G=load()
from collections import Counter
def f(I):
    H,W=len(I),len(I[0])
    bg=Counter(x for r in I for x in r).most_common(1)[0][0]
    # find line color: candidates = values != bg that appear in full uniform rows/cols
    def is_uniform_seq(seq): return len(set(seq))==1
    seprows=[r for r in range(H) if is_uniform_seq(I[r])]
    sepcols=[c for c in range(W) if is_uniform_seq([I[r][c] for r in range(H)])]
    sr=set(seprows); sc=set(sepcols)
    L=I[seprows[0]][0] if seprows else None
    pv = seprows[1]-seprows[0] if len(seprows)>1 else None
    ph = sepcols[1]-sepcols[0] if len(sepcols)>1 else None
    O=[row[:] for row in I]
    for col in range(W):
        rows=[r for r in range(H) if r not in sr and I[r][col]!=bg]
        if len(rows)>=2 and pv is not None:
            vals=set(I[r][col] for r in rows)
            for v in vals:
                rs=[r for r in rows if I[r][col]==v]
                if len(rs)>=2:
                    mn,mx=min(rs),max(rs)
                    for r in range(mn+pv,mx,pv):
                        if r not in sr: O[r][col]=v
    for row in range(H):
        cols=[c for c in range(W) if c not in sc and I[row][c]!=bg]
        if len(cols)>=2 and ph is not None:
            for v in set(I[row][c] for c in cols):
                cs=[c for c in cols if I[row][c]==v]
                if len(cs)>=2:
                    mn,mx=min(cs),max(cs)
                    for c in range(mn+ph,mx,ph):
                        if c not in sc: O[row][c]=v
    return O
